parameters.text:
==User Context --
Current Date & Time (Costa Rica, UTC-6): {{ $now.setZone('America/Costa_Rica').toFormat('yyyy-MM-dd, cccc, hh:mm a') }}
Action Type: {{ $json.action }}
User Message: {{ $json.chatInput }}

parameters.jsCode:
const output = $input.first().json.output || "";
let crmData = null;
let aiSuggestions = [];
let cleanOutput = output;

const crmMatch = cleanOutput.match(/<CRM>([\s\S]*?)<\/CRM>/);
if (crmMatch) {
  try {
    crmData = JSON.parse(crmMatch[1]);
    cleanOutput = cleanOutput.replace(crmMatch[0], '').trim();
  } catch (e) {
    console.error("Failed to parse CRM", e);
  }
}

const suggMatch = cleanOutput.match(/<AI_SUGGESTIONS>([\s\S]*?)<\/AI_SUGGESTIONS>/);
if (suggMatch) {
  try {
    aiSuggestions = JSON.parse(suggMatch[1]);
    cleanOutput = cleanOutput.replace(suggMatch[0], '').trim();
  } catch (e) {
    console.error("Failed to parse AI Suggestions", e);
  }
}

return [{
  json: {
    html: cleanOutput,
    ai_suggestions: aiSuggestions,
    has_crm: !!crmData,
    crm: crmData,
    session_id: $('Valid Request').item.json.body.sessionId
  }
}];

